#!/usr/bin/env node

/**
 * OpenSea Bid Timing Analyzer
 * 
 * This script analyzes the timing logs generated by the bidOnOpensea function
 * to identify performance bottlenecks and optimization opportunities.
 * 
 * Usage: node analyze-bid-timing.js [logfile]
 */

const fs = require('fs');
const path = require('path');

const logFile = process.argv[2] || path.join(__dirname, 'logs', 'opensea-bid-timing.log');

if (!fs.existsSync(logFile)) {
  console.error(`Log file not found: ${logFile}`);
  console.error('Make sure to run some bids first to generate timing data.');
  process.exit(1);
}

console.log(`📊 Analyzing OpenSea bid timing from: ${logFile}\n`);

// Read and parse log entries
const logContent = fs.readFileSync(logFile, 'utf8');
const logEntries = logContent
  .trim()
  .split('\n')
  .filter(line => line.trim())
  .map(line => {
    try {
      return JSON.parse(line);
    } catch (error) {
      console.warn('⚠️  Failed to parse log line:', line);
      return null;
    }
  })
  .filter(entry => entry !== null);

if (logEntries.length === 0) {
  console.log('No valid log entries found.');
  process.exit(0);
}

console.log(`📈 Found ${logEntries.length} bid attempts\n`);

// Analyze by bid type
const statsByType = {};
const stepStats = {};

logEntries.forEach(entry => {
  const { bidType, totalDuration, success, steps } = entry;
  
  if (!statsByType[bidType]) {
    statsByType[bidType] = {
      total: 0,
      successful: 0,
      failed: 0,
      durations: []
    };
  }
  
  statsByType[bidType].total++;
  if (success) {
    statsByType[bidType].successful++;
    statsByType[bidType].durations.push(totalDuration);
  } else {
    statsByType[bidType].failed++;
  }
  
  // Analyze step timings
  Object.entries(steps).forEach(([stepName, stepData]) => {
    if (!stepStats[stepName]) {
      stepStats[stepName] = {
        count: 0,
        totalDuration: 0,
        successful: 0,
        failed: 0,
        durations: []
      };
    }
    
    stepStats[stepName].count++;
    stepStats[stepName].totalDuration += stepData.duration;
    stepStats[stepName].durations.push(stepData.duration);
    
    if (stepData.success) {
      stepStats[stepName].successful++;
    } else {
      stepStats[stepName].failed++;
    }
  });
});

// Calculate statistics
function calculateStats(durations) {
  if (durations.length === 0) return { avg: 0, min: 0, max: 0, p95: 0 };
  
  const sorted = durations.sort((a, b) => a - b);
  const avg = durations.reduce((sum, d) => sum + d, 0) / durations.length;
  const min = sorted[0];
  const max = sorted[sorted.length - 1];
  const p95Index = Math.floor(sorted.length * 0.95);
  const p95 = sorted[p95Index] || max;
  
  return { avg, min, max, p95 };
}

// Display bid type summary
console.log('🎯 Bid Type Summary:');
console.log('═'.repeat(80));
Object.entries(statsByType).forEach(([bidType, stats]) => {
  const successRate = ((stats.successful / stats.total) * 100).toFixed(1);
  const timing = calculateStats(stats.durations);
  
  console.log(`${bidType.toUpperCase()} BIDS:`);
  console.log(`  Total: ${stats.total} | Success: ${stats.successful} | Failed: ${stats.failed} | Success Rate: ${successRate}%`);
  
  if (stats.durations.length > 0) {
    console.log(`  Timing: Avg: ${timing.avg.toFixed(0)}ms | Min: ${timing.min}ms | Max: ${timing.max}ms | P95: ${timing.p95.toFixed(0)}ms`);
  }
  console.log('');
});

// Display step performance
console.log('⚡ Step Performance Analysis:');
console.log('═'.repeat(80));

const sortedSteps = Object.entries(stepStats)
  .sort(([,a], [,b]) => (b.totalDuration / b.count) - (a.totalDuration / a.count))
  .slice(0, 15); // Top 15 slowest steps

sortedSteps.forEach(([stepName, stats]) => {
  const avgDuration = stats.totalDuration / stats.count;
  const successRate = ((stats.successful / stats.count) * 100).toFixed(1);
  const timing = calculateStats(stats.durations);
  
  console.log(`${stepName}:`);
  console.log(`  Count: ${stats.count} | Success Rate: ${successRate}% | Avg: ${avgDuration.toFixed(0)}ms`);
  console.log(`  Min: ${timing.min}ms | Max: ${timing.max}ms | P95: ${timing.p95.toFixed(0)}ms`);
  console.log('');
});

// Identify bottlenecks
console.log('🚀 Performance Recommendations:');
console.log('═'.repeat(80));

const slowSteps = Object.entries(stepStats)
  .filter(([, stats]) => (stats.totalDuration / stats.count) > 1000) // Steps averaging > 1 second
  .sort(([,a], [,b]) => (b.totalDuration / b.count) - (a.totalDuration / a.count));

if (slowSteps.length > 0) {
  console.log('🐌 Slowest steps (>1s average):');
  slowSteps.forEach(([stepName, stats]) => {
    const avgDuration = (stats.totalDuration / stats.count).toFixed(0);
    console.log(`  • ${stepName}: ${avgDuration}ms average`);
  });
  console.log('');
}

const failingSteps = Object.entries(stepStats)
  .filter(([, stats]) => stats.failed > 0)
  .sort(([,a], [,b]) => (b.failed / b.count) - (a.failed / a.count));

if (failingSteps.length > 0) {
  console.log('❌ Steps with failures:');
  failingSteps.forEach(([stepName, stats]) => {
    const failRate = ((stats.failed / stats.count) * 100).toFixed(1);
    console.log(`  • ${stepName}: ${stats.failed}/${stats.count} failures (${failRate}%)`);
  });
  console.log('');
}

// Recent trends (last 10 entries)
const recentEntries = logEntries.slice(-10);
const recentSuccessRate = ((recentEntries.filter(e => e.success).length / recentEntries.length) * 100).toFixed(1);
const recentAvgDuration = (recentEntries.reduce((sum, e) => sum + e.totalDuration, 0) / recentEntries.length).toFixed(0);

console.log('📊 Recent Performance (last 10 bids):');
console.log(`  Success Rate: ${recentSuccessRate}% | Average Duration: ${recentAvgDuration}ms`);

console.log('\n✅ Analysis complete!');